systemCss:
/* SimpleKit V2 system v1. Opt-in: foundations.css + data-v2-system="1".
   No global resets, legacy selectors, formula or storage behavior. */
.sk-v2[data-v2-system="1"] {
  --v2-reading-width: 44rem;
  --v2-form-width: 34rem;
  --v2-layout-gap: clamp(1rem, 3vw, 2rem);
  --v2-success: #006f62;
  --v2-warning: #8d4b08;
  --v2-disabled: #eef1f6;
  margin: 0;
  overflow-wrap: anywhere;
}
.sk-v2[data-v2-system="1"] [hidden] { display: none !important; }
.sk-v2[data-v2-system="1"] :where(main,section,article,aside,fieldset,div) { min-width: 0; }
.sk-v2[data-v2-system="1"] :where(h1) { font-size: var(--v2-title-md); line-height: 1.12; }
.sk-v2[data-v2-system="1"] :where(h2) { font-size: clamp(1.5rem, 1.2rem + 1vw, 2rem); line-height: 1.2; }
.sk-v2[data-v2-system="1"] :where(h3) { line-height: 1.3; }
.sk-v2[data-v2-system="1"] .v2s-wrap { width: min(calc(100% - 2 * var(--v2-gutter)), var(--v2-content-width)); margin-inline: auto; }
.sk-v2[data-v2-system="1"] .v2s-stack { display: grid; gap: var(--v2-space-5); }
.sk-v2[data-v2-system="1"] .v2s-header { background: var(--v2-surface); border-bottom: 1px solid var(--v2-border); }
.sk-v2[data-v2-system="1"] .v2s-header-inner { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: .5rem 1rem; padding-block: .5rem; }
.sk-v2[data-v2-system="1"] .v2s-brand { display: inline-flex; align-items: center; gap: .625rem; min-height: 44px; color: var(--v2-navy); text-decoration: none; font-weight: 700; letter-spacing: -.025em; }
.sk-v2[data-v2-system="1"] .v2s-brand svg { width: 26px; height: 26px; color: var(--v2-blue); }
.sk-v2[data-v2-system="1"] .v2s-nav { display: flex; flex-wrap: wrap; gap: .25rem .5rem; width: 100%; }
.sk-v2[data-v2-system="1"] :where(.v2s-nav a,.v2s-footer a,.v2s-section-nav a,.v2s-breadcrumb a) { display: inline-flex; align-items: center; min-height: 44px; padding: .5rem; }
.sk-v2[data-v2-system="1"] .v2s-nav a { color: var(--v2-navy); text-decoration: none; border-radius: var(--v2-radius-sm); }
.sk-v2[data-v2-system="1"] .v2s-nav a:hover { background: var(--v2-tint); }
.sk-v2[data-v2-system="1"] .v2s-nav [aria-current="page"] { color: var(--v2-blue); background: var(--v2-blue-soft); font-weight: 700; }
.sk-v2[data-v2-system="1"] .v2s-menu { min-width: 44px; min-height: 44px; border: 1px solid var(--v2-control-border); border-radius: var(--v2-radius-sm); color: var(--v2-navy); background: var(--v2-surface); padding: .5rem .75rem; cursor: pointer; }
.sk-v2[data-v2-system="1"] .v2s-skip { position: absolute; top: .5rem; left: 1rem; transform: translateY(-200%); z-index: 10; }
.sk-v2[data-v2-system="1"] .v2s-skip:focus { transform: none; }
.sk-v2[data-v2-system="1"] .v2s-breadcrumb { padding-block: .5rem; font-size: var(--v2-text-sm); }
.sk-v2[data-v2-system="1"] .v2s-breadcrumb ol { display: flex; flex-wrap: wrap; align-items: center; list-style: none; gap: .25rem; margin: 0; padding: 0; }
.sk-v2[data-v2-system="1"] .v2s-breadcrumb li+li::before { content: "/"; color: var(--v2-slate); margin-inline: .25rem .5rem; }
.sk-v2[data-v2-system="1"] .v2s-intro { display: grid; gap: .75rem; max-width: var(--v2-reading-width); padding-block: 1rem 1.5rem; }
.sk-v2[data-v2-system="1"] .v2s-layout { display: grid; gap: var(--v2-layout-gap); padding-bottom: 2rem; align-items: start; }
.sk-v2[data-v2-system="1"] .v2s-surface { background: var(--v2-surface); border: 1px solid var(--v2-border); border-radius: var(--v2-radius-card); padding: clamp(1rem, 3vw, 1.5rem); box-shadow: var(--v2-shadow-soft); }
.sk-v2[data-v2-system="1"] .v2s-prose { max-width: var(--v2-reading-width); display: grid; gap: 1.5rem; }
.sk-v2[data-v2-system="1"] .v2s-prose :where(section) { display: grid; gap: .875rem; }
.sk-v2[data-v2-system="1"] .v2s-prose :where(ul,ol) { margin: 0; padding-left: 1.5rem; }
.sk-v2[data-v2-system="1"] .v2s-prose li+li { margin-top: .5rem; }
.sk-v2[data-v2-system="1"] :where([id]) { scroll-margin-top: 1rem; }
.sk-v2[data-v2-system="1"] .v2s-section-nav { display: grid; gap: .25rem; }
.sk-v2[data-v2-system="1"] .v2s-section-nav a { text-underline-offset: .2em; border-radius: .5rem; }
.sk-v2[data-v2-system="1"] .v2s-related { display: grid; gap: .75rem; }
.sk-v2[data-v2-system="1"] .v2s-related a { display: flex; min-height: 44px; align-items: center; justify-content: space-between; gap: 1rem; padding: .75rem 1rem; border: 1px solid var(--v2-border); border-radius: var(--v2-radius-sm); text-decoration: none; font-weight: 700; }
.sk-v2[data-v2-system="1"] .v2s-related a:hover { background: var(--v2-tint); border-color: var(--v2-blue); }
.sk-v2[data-v2-system="1"] .v2s-note { padding: 1rem; border: 1px solid var(--v2-control-border); border-left: 4px solid var(--v2-blue); border-radius: var(--v2-radius-sm); background: var(--v2-blue-soft); }
.sk-v2[data-v2-system="1"] .v2s-note[data-tone="warning"] { border-left-color: var(--v2-warning); background: var(--v2-amber-soft); }
.sk-v2[data-v2-system="1"] .v2s-note[data-tone="error"] { border-left-color: var(--v2-error); background: #fff1f2; }
.sk-v2[data-v2-system="1"] .v2s-note[data-tone="success"] { border-left-color: var(--v2-success); background: var(--v2-teal-soft); }
.sk-v2[data-v2-system="1"] .v2s-grid { display: grid; grid-template-columns: repeat(auto-fit,minmax(min(100%,14rem),1fr)); gap: 1rem; }
.sk-v2[data-v2-system="1"] .v2s-field { display: grid; gap: .375rem; align-content: start; }
.sk-v2[data-v2-system="1"] .v2s-field label, .sk-v2[data-v2-system="1"] legend { font-weight: 700; }
.sk-v2[data-v2-system="1"] .v2s-control { width: 100%; min-height: 44px; min-width: 0; padding: .625rem .75rem; border: 1px solid var(--v2-control-border); border-radius: var(--v2-radius-sm); color: var(--v2-navy); background: var(--v2-surface); }
.sk-v2[data-v2-system="1"] .v2s-control[aria-invalid="true"] { border: 2px solid var(--v2-error); }
.sk-v2[data-v2-system="1"] .v2s-help { color: var(--v2-slate); font-size: var(--v2-text-sm); }
.sk-v2[data-v2-system="1"] .v2s-error { color: var(--v2-error); font-size: var(--v2-text-sm); font-weight: 700; }
.sk-v2[data-v2-system="1"] fieldset { margin: 0; border: 1px solid var(--v2-border); border-radius: var(--v2-radius-sm); padding: 1rem; }
.sk-v2[data-v2-system="1"] .v2s-choice { display: flex; align-items: center; gap: .625rem; min-height: 44px; cursor: pointer; }
.sk-v2[data-v2-system="1"] .v2s-choice input { width: 20px; height: 20px; accent-color: var(--v2-blue); margin: 0; flex: none; }
.sk-v2[data-v2-system="1"] input[type="range"].v2s-control { padding: .5rem 0; accent-color: var(--v2-blue); }
.sk-v2[data-v2-system="1"] .v2s-actions { display: flex; flex-wrap: wrap; gap: .75rem; }
.sk-v2[data-v2-system="1"] .v2s-actions .v2-button { border-radius: var(--v2-radius-sm); padding: .625rem 1rem; }
.sk-v2[data-v2-system="1"] :where(button,input,select):disabled { color: var(--v2-slate); background: var(--v2-disabled); cursor: not-allowed; opacity: 1; }
.sk-v2[data-v2-system="1"] .v2s-kpi { display: grid; gap: .25rem; }
.sk-v2[data-v2-system="1"] .v2s-kpi dt { color: var(--v2-slate); font-size: var(--v2-text-sm); }
.sk-v2[data-v2-system="1"] .v2s-kpi dd { margin: 0; font-weight: 700; font-size: clamp(1.5rem,3vw,2rem); font-variant-numeric: tabular-nums; }
.sk-v2[data-v2-system="1"] .v2s-chart { margin: 0; display: grid; gap: .5rem; }
.sk-v2[data-v2-system="1"] .v2s-chart svg { display: block; width: 100%; height: auto; }
.sk-v2[data-v2-system="1"] .v2s-table-scroll { max-width: 100%; overflow-x: auto; border: 1px solid var(--v2-border); border-radius: var(--v2-radius-sm); }
.sk-v2[data-v2-system="1"] table { border-collapse: collapse; width: 100%; font-variant-numeric: tabular-nums; font-size: var(--v2-text-sm); }
.sk-v2[data-v2-system="1"] caption { padding: .75rem; text-align: left; font-weight: 700; }
.sk-v2[data-v2-system="1"] th { background: var(--v2-tint); text-align: left; }
.sk-v2[data-v2-system="1"] :where(th,td) { padding: .75rem; border-bottom: 1px solid var(--v2-border); white-space: nowrap; }
.sk-v2[data-v2-system="1"] details { border: 1px solid var(--v2-border); border-radius: var(--v2-radius-sm); padding: .25rem 1rem; }
.sk-v2[data-v2-system="1"] summary { min-height: 44px; padding-block: .625rem; cursor: pointer; font-weight: 700; }
.sk-v2[data-v2-system="1"] details[open] { padding-bottom: 1rem; }
.sk-v2[data-v2-system="1"] .v2s-empty { padding: 1.5rem; text-align: center; border: 1px dashed var(--v2-control-border); border-radius: var(--v2-radius-sm); color: var(--v2-slate); }
.sk-v2[data-v2-system="1"] .v2s-footer { padding-block: 1.5rem; border-top: 1px solid var(--v2-border); background: var(--v2-surface); }
.sk-v2[data-v2-system="1"] .v2s-footer-inner { display: grid; gap: 1rem; }
.sk-v2[data-v2-system="1"] .v2s-footer nav { display: flex; flex-wrap: wrap; gap: .25rem .5rem; }
@media (min-width: 48rem) {
  .sk-v2[data-v2-system="1"] .v2s-nav { width: auto; }
  .sk-v2[data-v2-system="1"] .v2s-layout { grid-template-columns: minmax(0,1fr) minmax(14rem,20rem); }
  .sk-v2[data-v2-system="1"] .v2s-layout--editorial { grid-template-areas: "content navigation"; }
  .sk-v2[data-v2-system="1"] .v2s-layout--editorial article { grid-area: content; }
  .sk-v2[data-v2-system="1"] .v2s-layout--editorial aside { grid-area: navigation; }
  .sk-v2[data-v2-system="1"] .v2s-layout--calculator { grid-template-columns: minmax(0,.95fr) minmax(0,1.05fr); }
  .sk-v2[data-v2-system="1"] .v2s-footer-inner { grid-template-columns: 1fr 1fr; }
}
@media (forced-colors: active) {
  .sk-v2[data-v2-system="1"] :where(.v2s-surface,.v2s-control,.v2s-note,.v2s-related a,.v2s-menu,.v2s-table-scroll,details) { border-color: CanvasText; box-shadow: none; }
  .sk-v2[data-v2-system="1"] .v2s-chart svg { forced-color-adjust: none; background: #fff; border: 1px solid #52627c; }
}
@media print {
  .sk-v2[data-v2-system="1"] :where(.v2s-header,.v2s-skip,.v2s-section-nav,.v2s-actions) { display: none; }
  .sk-v2[data-v2-system="1"] :where(.v2s-layout,.v2s-layout--calculator) { display: block; }
  .sk-v2[data-v2-system="1"] :where(.v2s-surface,.v2s-note) { box-shadow: none; break-inside: avoid; }
  .sk-v2[data-v2-system="1"] .v2s-table-scroll { overflow: visible; }
  .sk-v2[data-v2-system="1"] :where(th,td) { white-space: normal; }
}
